import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.simple.JdbcClient;

/** Every building's rooms and bookings live on one shard. */
public class Shards {
    private static final Map<String, Integer> BUILDINGS = Map.of("main-library", 0, "science-library", 1);

    private final List<JdbcClient> shards;

    public Shards(List<JdbcClient> shards) {
        this.shards = shards;
    }

    public JdbcClient forBuilding(String buildingSlug) {
        Integer n = BUILDINGS.get(buildingSlug);
        if (n == null) {
            throw new IllegalArgumentException("no shard for building " + buildingSlug);
        }
        return shards.get(n);
    }
}
